// ==UserScript==
// @name         YTM-DeSlop: AI Music Slop Blocker
// @namespace      https://github.com/grave0x/YTM-DeSlop
// @version      1.0.0
// @description    Block AI Music content on YouTube Music and YouTube
// @author         Generated by omp tool
// @match        https://music.youtube.com/*
// @match        https://www.youtube.com/*
// @match        https://*.youtube.com/*
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_deleteValue
// @grant        GM_listValues
// @grant        GM_notification
// @grant        GM_xmlhttpRequest
// @updateURL    https://raw.githubusercontent.com/grave0x/YTM-DeSlop/main/src/userscript.js
// @downloadURL  https://raw.githubusercontent.com/grave0x/YTM-DeSlop/main/src/userscript.js
// ==/UserScript==

/**
 * YTM-DeSlop AI Music Slop Blocker
 *
 * This userscript blocks/heavily reduces AI-generated music content on
 * music.youtube.com and youtube.com using community-maintained blocklists.
 *
 * Sources aggregated:
 *   - Stevoisiak/Stevos-AI-Blocklist (GenAI-Blocklist.txt)
 *   - muhdiboy ytm_ai_blocklist.txt (YouTube Music AI channels)
 *   - Override92/AiSList (aislist_blocklist.txt + aislist_warnlist.txt)
 *   - CevvalYoutubeAIBlocklist (uBlock AI-music blocklist)
 *
 * Features:
 *   1. Automatic blocking of known AI music channels/artists
 *   2. Warning mode for medium-confidence entries
 *   3. Manual block/add to blocklist UI
 *   4. Local storage backup/restore of user blocks
 *   5. Real-time channel/artist/song detection
 */

// ---------------------------------------------------------------------------
// Configuration & State
// ---------------------------------------------------------------------------

const CONFIG = {
    // Blocklist data loaded at runtime from blocklist.json
    blocklist: null,

    // User-configured preferences
    preferences: {
        // Block high-confidence entries (true) or warn only (false)
        blockHighConfidence: true,
        // Show warnings for medium-confidence entries (true) or silently skip (false)
        showMediumConfidenceWarnings: true,
        // Automatically block new AI channels detected
        autoBlockNew: true,
    },

    // Key domains to block
    domains: {
        musicYouTube: "music.youtube.com",
        youtube: "youtube.com",
    },
};

// State stored in GM_* localStorage
const STATE_KEY = "YTM-DeSlop-state";

// Channel/artist/keyword block storage
let blockedChannels = new Set();     // @handles or UC-ids user manually blocked
let blockedArtists = new Set();      // Artist names/user-defined
let blockedKeywords = new Set();     // Title keywords to skip

// ---------------------------------------------------------------------------
// Load blocklist data
// ---------------------------------------------------------------------------

/**
 * Fetch and parse the aggregated blocklist JSON.
 * Expected format: {generated_at, total, sources, entries[]}
 * Each entry: {source, kind, value, confidence, raw}
 */
async function loadBlocklist() {
    try {
        // Blocklist is fetched from the GitHub raw URL (see below).
        const jsonUrl =
            "https://raw.githubusercontent.com/grave0x/YTM-DeSlop/main/src/data/blocklist.json";

        const response = await GM_xmlhttpRequest({
            method: "GET",
            url: jsonUrl,
            timeout: 15000,
        });

        if (response.status !== 200) {
            console.warn("[YTM-DeSlop] Failed to fetch blocklist, status:", response.status);
            return null;
        }

        const data = JSON.parse(response.responseText);
        const sourceNames = Array.isArray(data.sources)
            ? data.sources.map(s => (typeof s === "string" ? s : s.name || "unknown")).join(", ")
            : "unknown";
        console.log("[YTM-DeSlop] Loaded blocklist:", data.total, "entries from", sourceNames);
        return Array.isArray(data.entries) ? data.entries : null;
    } catch (err) {
        console.error("[YTM-DeSlop] Error loading blocklist:", err);
        return null;
    }
}

/**
 * Canonicalize a value for matching (lowercase, trim)
 */
function canonicalize(value) {
    if (!value) return "";
    return value.trim().toLowerCase();
}

// ---------------------------------------------------------------------------
// Lookup indexes (built once from blocklist; O(1) matching)
// ---------------------------------------------------------------------------

const channelIndex = new Set();   // canonical handles ("@name") and UC-ids
const artistIndex = new Set();    // canonical artist names
const keywordIndex = new Set();   // canonical title keywords

/**
 * Build Set indexes from blocklist entries for O(1) matching
 * instead of scanning all entries on every DOM mutation.
 */
function buildLookupIndexes(entries) {
    channelIndex.clear();
    artistIndex.clear();
    keywordIndex.clear();

    for (const entry of entries) {
        const value = canonicalize(entry.value);
        if (!value) continue;
        switch (entry.kind) {
            case "channel":
                channelIndex.add(value);
                break;
            case "artist":
                artistIndex.add(value);
                break;
            case "keyword":
                // Ignore trivially-short keywords that would over-match
                if (value.length >= 4) keywordIndex.add(value);
                break;
        }
    }

    console.log("[YTM-DeSlop] Indexes built:", {
        channels: channelIndex.size,
        artists: artistIndex.size,
        keywords: keywordIndex.size,
    });
}

/**
 * YouTube channel ID regex (declared before use)
 */
const CHANNEL_ID_RE = /^UC[A-Za-z0-9_-]{22}$/;

/**
 * Check if a YouTube channel handle/ID is blocked.
 * O(1): exact Set lookups; entry param kept for API compat.
 */
function isChannelBlocked(channelIdOrHandle, _blocklistEntries) {
    const canonical = canonicalize(channelIdOrHandle);
    if (!canonical) return false;

    if (channelIndex.has(canonical)) return true;

    // Channel-name pages render as "- Topic" / "VEVO" variants of artist names
    const asArtist = canonical.replace(/ - topic( vevo)?$/, "").replace(/ vevo$/, "");
    if (asArtist !== canonical && artistIndex.has(asArtist)) return true;

    return false;
}

/**
 * Check if an artist name is blocked.
 * Exact match plus " - Topic"/"VEVO" channel-name variants; no substring
 * matching (an entry like "ai" would otherwise match "wait", "rain").
 */
function isArtistBlocked(artistName, _blocklistEntries) {
    const canonical = canonicalize(artistName);
    if (!canonical) return false;

    if (artistIndex.has(canonical)) return true;
    if (canonical.startsWith("@") && channelIndex.has(canonical)) return true;

    const asArtist = canonical.replace(/ - topic( vevo)?$/, "").replace(/ vevo$/, "");
    return asArtist !== canonical && artistIndex.has(asArtist);
}

/**
 * Check if a title contains a blocked keyword. O(keywords) with early exit.
 */
function isTitleBlocked(title, _blocklistEntries) {
    if (!title) return false;

    const canonicalTitle = canonicalize(title);

    for (const keyword of keywordIndex) {
        if (canonicalTitle.includes(keyword)) return true;
    }
    return false;
}

// ---------------------------------------------------------------------------
// Page initialization & DOM observers
// ---------------------------------------------------------------------------

/**
 * Determine if we're on a relevant YouTube page
 */
function isRelevantPage() {
    const hostname = window.location.hostname.toLowerCase();
    return (
        hostname === CONFIG.domains.musicYouTube ||
        hostname === CONFIG.domains.youtube ||
        hostname.endsWith(`.youtube.com`)
    );
}

/**
 * Initialize the script when the page loads
 */
function initialize() {
    if (!isRelevantPage()) return;

    // Load blocklist data
    loadBlocklist().then(entries => {
        if (!entries) {
            console.warn("[YTM-DeSlop] No blocklist loaded; manual blocks still active.");
            loadUserState();
            setupObservers();
            return;
        }
        CONFIG.blocklist = entries;
        buildLookupIndexes(entries);

        // Load user preferences and blocked list from storage
        loadUserState();

        // Set up observers for dynamic content
        setupObservers();
    });
}

/**
 * Load user preferences and manually added blocks from GM_* storage
 */
function loadUserState() {
    try {
        const stored = GM_getValue(STATE_KEY, null);
        if (stored) {
            const parsed = JSON.parse(stored);
            blockedChannels = new Set(parsed.blockedChannels || []);
            blockedArtists = new Set(parsed.blockedArtists || []);
            blockedKeywords = new Set(parsed.blockedKeywords || []);
            console.log("[YTM-DeSlop] Loaded user state:", {
                blockedChannels: blockedChannels.size,
                blockedArtists: blockedArtists.size,
                blockedKeywords: blockedKeywords.size,
            });
        }
    } catch (err) {
        console.warn("[YTM-DeSlop] Error loading user state:", err);
    }
}

/**
 * Save user state to GM_* storage
 */
function saveUserState() {
    try {
        const state = {
            blockedChannels: Array.from(blockedChannels),
            blockedArtists: Array.from(blockedArtists),
            blockedKeywords: Array.from(blockedKeywords),
        };
        GM_setValue(STATE_KEY, JSON.stringify(state));
        console.log("[YTM-DeSlop] Saved user state");
    } catch (err) {
        console.error("[YTM-DeSlop] Error saving user state:", err);
    }
}

/**
 * Set up MutationObservers to detect new content on the page
 */
function setupObservers() {
    if (!CONFIG.blocklist) return;

    // Observe the video player area for title/artist changes
    const observerConfig = {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ["class", "id", "title"],
    };

    const pageObserver = new MutationObserver(handleDomChanges);
    pageObserver.observe(document.body, observerConfig);

    // Also observe specific YouTube Music player elements
    const playerRoot = document.querySelector('#primary-inner');
    if (playerRoot) {
        const playerObserver = new MutationObserver(handlePlayerChanges);
        playerObserver.observe(playerRoot, observerConfig);
    }
}

/**
 * Handle DOM changes - check for AI-blockable content
 */
function handleDomChanges(mutations) {
    if (!CONFIG.blocklist) return;

    for (const mutation of mutations) {
        // Check for video title elements
        const titleElements = mutation.target.querySelectorAll(
            '.ytd-video-title-renderer, .style-scope.ytd-grid-video-renderer'
        );

        for (const el of titleElements) {
            const title = el.innerText || el.textContent || "";
            if (title && isTitleBlocked(title, CONFIG.blocklist)) {
                applyBlockStyle(el, "title");
            }
        }

        // Check for channel/artist name elements
        const channelElements = mutation.target.querySelectorAll(
            '.ytd-channel-name, .style-scope.ytd-channel-name, ' +
            '.ytd-video-owner-wrapper .ytd-channel-name'
        );

        for (const el of channelElements) {
            const channelName = el.innerText || el.textContent || "";
            if (channelName) {
                // Check against blocklist
                if (isChannelBlocked(channelName, CONFIG.blocklist)) {
                    applyBlockStyle(el, "channel");
                }
                // Check user-manually blocked
                if (blockedChannels.has(canonicalize(channelName))) {
                    applyBlockStyle(el, "user-block");
                }
            }
        }

        // Check for artist name elements in music context
        const artistElements = mutation.target.querySelectorAll(
            '.ytd-player-bar .ytd-long-form-description-span, ' +
            '.ytd-rock-carousel-container .ytd-video-secondary-info-renderer'
        );

        for (const el of artistElements) {
            const artistText = el.innerText || el.textContent || "";
            if (artistText) {
                if (isArtistBlocked(artistText, CONFIG.blocklist)) {
                    applyBlockStyle(el, "artist");
                }
                if (blockedArtists.has(canonicalize(artistText))) {
                    applyBlockStyle(el, "user-block");
                }
            }
        }
    }
}

/**
 * Handle YouTube Music player specific changes
 */
function handlePlayerChanges(mutations) {
    if (!CONFIG.blocklist) return;

    for (const mutation of mutations) {
        // Check current video title
        const titleEl = document.querySelector('.ytp-title');
        if (titleEl) {
            const title = titleEl.innerText || titleEl.textContent || "";
            if (title && isTitleBlocked(title, CONFIG.blocklist)) {
                // Add warning indicator
                titleEl.style.setProperty("--ytm-block", "true", "important");
            }
        }

        // Check current artist
        const artistEl = document.querySelector('.ytdPlayerInlineMetadata')
            ?.querySelector('.ytp-time-status');
        if (artistEl) {
            const artistText = artistEl.innerText || artistEl.textContent || "";
            if (artistText && (isArtistBlocked(artistText, CONFIG.blocklist) ||
                    blockedArtists.has(canonicalize(artistText)))) {
                artistEl.style.setProperty("--ytm-block", "true", "important");
            }
        }
    }
}

/**
 * Apply blocking style to an element
 * - Add warning label
 * - Gray out / hide content based on confidence level
 */
function applyBlockStyle(element, blockType) {
    if (!element || !element.parentNode) return;

    const isHighConfidence = blockType !== "user-block";

    // Add a warning indicator
    const indicator = document.createElement("span");
    indicator.style.cssText = `
        position: relative;
        display: inline-block;
        width: 12px;
        height: 12px;
        background: ${isHighConfidence ? "#ff0000" : "#ffa500"};
        border-radius: 50%;
        margin-left: 4px;
        box-shadow: 0 0 0 2px ${element.style.color || "white"};
        cursor: help;
    `;

    // Insert before the element text
    element.parentNode.insertBefore(indicator, element);

    // Add title attribute for tooltip
    indicator.title = `YTM-DeSlop: ${blockType.toUpperCase()} content blocked`;

    // Apply reduced opacity for blocked content
    element.style.opacity = isHighConfidence ? "0.3" : "0.5";
    element.style.textDecoration = "line-through";
    element.style.textDecorationColor = "#ff0000";
    element.style.textDecorationThickness = "1px";
}

/**
 * Add manual block UI button to the page
 */
function addManualBlockUI() {
    const button = document.createElement("button");
    button.style.cssText = `
        position: fixed;
        bottom: 20px;
        right: 20px;
        z-index: 2147483647;
        background: #ff0000;
        color: white;
        border: none;
        border-radius: 20px;
        padding: 8px 16px;
        font-family: Arial, sans-serif;
        font-size: 12px;
        cursor: pointer;
    `;
    button.innerText = "🚫 Block";
    button.title = "Block this channel/artist/song";

    button.onclick = async function() {
        // Get current context
        const selectedText = window.getSelection().toString().trim();
        const currentChannel = document.querySelector('.ytd-channel-name');
        const currentArtist = document.querySelector('.ytd-player-bar .ytp-time-status');
        const currentTitle = document.querySelector('.ytp-title');

        if (selectedText) {
            // Block the selected text as a keyword
            blockedKeywords.add(selectedText.toLowerCase());
            addToBlocklistUI("keyword", selectedText);
        } else if (currentChannel) {
            blockedChannels.add(currentChannel.innerText.trim());
            addToBlocklistUI("channel", currentChannel.innerText.trim());
        } else if (currentArtist) {
            blockedArtists.add(currentArtist.innerText.trim());
            addToBlocklistUI("artist", currentArtist.innerText.trim());
        } else if (currentTitle) {
            // Try to extract artist from title
            addToBlocklistUI("artist", currentTitle.innerText.trim());
        }

        saveUserState();
        showNotification("Blocked successfully!");
    };

    document.body.appendChild(button);
}

/**
 * Add entry to the blocklist UI panel
 */
function addToBlocklistUI(type, value) {
    // Create a small unsaved-changes indicator
    const panel = document.createElement("div");
    panel.style.cssText = `
        position: fixed;
        top: 20px;
        right: 20px;
        background: #222;
        color: white;
        padding: 12px;
        border-radius: 8px;
        font-size: 12px;
        z-index: 2147483647;
        max-width: 300px;
    `;
    panel.innerHTML = `
        <strong>YTM-DeSlop</strong> • <em>${type}</em>: ${value}<br>
        <span style="font-size: 10px; opacity: 0.7;">Saved to local storage</span>
    `;

    document.body.appendChild(panel);

    // Auto-remove after 3 seconds
    setTimeout(() => panel.remove(), 3000);
}

/**
 * Show a browser notification
 */
function showNotification(message) {
    if (!("Notification" in window)) return;
    if (Notification.permission === "granted") {
        new Notification("YTM-DeSlop", { body: message });
    } else if (Notification.permission !== "denied") {
        Notification.requestPermission().then(permission => {
            if (permission === "granted") {
                new Notification("YTM-DeSlop", { body: message });
            }
        });
    }
}

// ---------------------------------------------------------------------------
// Initialize on load
// ---------------------------------------------------------------------------

// For userscripts: initialize immediately
if (window.location.href.includes("youtube.com") || window.location.href.includes("music.youtube.com")) {
    initialize();
    addManualBlockUI();
}

// For extension contexts, the popup will trigger initialization